import csv


class CSVProcessor:
    SUCCESS = 1
    FAILURE = 0
    DEFAULT_ENCODING = 'utf-8'

    def __init__(self):
        pass

    def _read_csv_file(self, file_name):
        """Extracted method: reads CSV file and returns (title, data)."""
        data = []
        with open(file_name, 'r') as file:
            reader = csv.reader(file)
            title = next(reader)
            for row in reader:
                data.append(row)
        return title, data

    def _write_csv_file(self, data, file_name):
        """Extracted method: writes data to CSV file, returns status code."""
        try:
            with open(file_name, 'w', newline='') as file:
                writer = csv.writer(file)
                writer.writerows(data)
            return self.SUCCESS
        except:
            return self.FAILURE

    def _get_column_data(self, data, column_index):
        """Extracted method: retrieves and transforms the specified column."""
        column_data = [row[column_index].upper() for row in data]
        return column_data

    def _build_processed_data(self, title, column_data):
        """Extracted method: builds the new data structure for writing."""
        return [title, column_data]

    def _get_processed_file_name(self, original_file_name):
        """Extracted method: generates the processed file name."""
        base_name = original_file_name.split('.')[0]
        return base_name + '_process.csv'

    def read_csv(self, file_name):
        return self._read_csv_file(file_name)

    def write_csv(self, data, file_name):
        return self._write_csv_file(data, file_name)

    def process_csv_data(self, N, save_file_name):
        title, data = self.read_csv(save_file_name)
        column_data = self._get_column_data(data, N)
        new_data = self._build_processed_data(title, column_data)
        processed_file_name = self._get_processed_file_name(save_file_name)
        return self.write_csv(new_data, processed_file_name)
